<!-- homepage video js june 2026 -->
 <script>
jQuery(document).ready(function ($) {

    // =========================
    // Load More / View Less
    // =========================

    const initialItems = 3;
    const $cards = $(".video-card");

    // Initial state
    $cards.hide().slice(0, initialItems).show();

    $("#loadMore").on("click", function (e) {

        e.preventDefault();

        const $btn = $(this);

        // Check if hidden cards exist
        if ($cards.filter(":hidden").length > 0) {

            // Show remaining cards
            $cards.filter(":hidden").slideDown();

            // Change button text
            $btn.text("View Less");

        } else {

            // Hide extra cards only
            $cards.slice(initialItems).slideUp();

            // Change button text
            $btn.text("Load More");

            // Optional scroll to section
            $('html, body').animate({
                scrollTop: $cards.first().offset().top - 100
            }, 500);

        }

    });


    // =========================
    // Video Card Functions
    // =========================

    const cards = document.querySelectorAll('.ts-card');

    cards.forEach(card => {

        const video = card.querySelector('video');
        const muteWrap = card.querySelector('.muteunmute');
        const muteIcon = card.querySelector('.mute');
        const unmuteIcon = card.querySelector('.unmute');

        // Skip if video not found
        if (!video) return;

        // Default muted
        video.muted = true;

        // Default icons
        if (muteIcon) muteIcon.style.display = "inline-block";
        if (unmuteIcon) unmuteIcon.style.display = "none";

        // Hover play
        card.addEventListener('mouseenter', () => {

            video.play()
                .then(() => {
                    card.classList.add('playing');
                })
                .catch(() => {});

        });

        // Mouse leave
        card.addEventListener('mouseleave', () => {

            video.pause();
            video.currentTime = 0;

            card.classList.remove('playing');

            // Reset mute
            video.muted = true;

            // Reset icons
            if (muteIcon) muteIcon.style.display = "inline-block";
            if (unmuteIcon) unmuteIcon.style.display = "none";

        });

        // Mute / Unmute
        if (muteWrap) {

            muteWrap.addEventListener('click', (e) => {

                e.stopPropagation();

                video.muted = !video.muted;

                if (video.muted) {

                    if (muteIcon) muteIcon.style.display = "inline-block";
                    if (unmuteIcon) unmuteIcon.style.display = "none";

                } else {

                    if (muteIcon) muteIcon.style.display = "none";
                    if (unmuteIcon) unmuteIcon.style.display = "inline-block";

                }

            });

        }

        // Open Modal
        card.addEventListener('click', (e) => {

            if (e.target.closest('.muteunmute')) return;
            if (e.target.closest('.ts-expand')) return;

            const src = card.dataset.video;

            if (typeof openModal === "function" && src) {
                openModal(e, src);
            }

        });

    });


    // =========================
    // ESC Close Modal
    // =========================

    document.addEventListener('keydown', e => {

        if (e.key === 'Escape') {

            if (typeof closeModal === "function") {
                closeModal();
            }

        }

    });

});
</script>
